import React, { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';
import axios from 'axios';
import Modal from 'react-modal';

Modal.setAppElement('#root');

const HomePage = () => {
  const location = useLocation();
  const [userInfo, setUserInfo] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [connectedOrgs, setConnectedOrgs] = useState([]);

  useEffect(() => {
    const fetchUserInfo = async () => {
      try {
        const accessToken = location.state.accessToken;
        const response = await axios.get('http://localhost:3001/salesforce/user-info', {
          params: { accessToken },
        });
        setUserInfo(response.data);
      } catch (error) {
        setError('Failed to load user information.');
      }
    };

    fetchUserInfo();
  }, [location.state.accessToken]);

  const handleListConnectedOrgs = async () => {
    setLoading(true);
    setMessage('');
    try {
      const response = await axios.get('http://localhost:3001/connectedOrgs');
      setConnectedOrgs(response.data.orgs);
    } catch (error) {
      setMessage('Failed to list connected orgs.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <h1>Welcome to the Home Page</h1>
      {error ? (
        <p>{error}</p>
      ) : userInfo ? (
        <div>
          <p>User ID: {userInfo.user_id}</p>
          <p>Name: {userInfo.name}</p>
          <p>Email: {userInfo.email}</p>
        </div>
      ) : (
        <p>Loading user information...</p>
      )}
      <button onClick={handleListConnectedOrgs} disabled={loading}>List Connected Orgs</button>
      {message && <p>{message}</p>}
      <div>
        {connectedOrgs.map(org => (
          <div key={org.username}>
            <p>{org.username}</p>
            <p>{org.orgId}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default HomePage;
